theme.lxqt X11 + Openbox:
Steps {
    steps: [
        File(
            WriteFile {
                path: "/c/openbox/rc.xml",
                content: "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<openbox_config xmlns=\"http://openbox.org/3.4/rc\" xmlns:xi=\"http://www.w3.org/2001/XInclude\">\n<resistance>\n  <strength>10</strength>\n</resistance>\n<theme>\n  <name>Onyx-Citrus</name>\n  <titleLayout>NLIMC</titleLayout>\n  <!--\n      available characters are NDSLIMC, each can occur at most once.\n      <name>в комментарии не трогается</name>\n  -->\n  <keepBorder>yes</keepBorder>\n  <font place=\"ActiveWindow\">\n    <name>sans</name>\n    <size>8</size>\n  </font>\n</theme>\n<desktops>\n  <names>\n    <name>1</name>\n  </names>\n</desktops>\n</openbox_config>\n",
            },
        ),
        File(
            Run {
                argv: [
                    "openbox",
                    "--reconfigure",
                ],
                timeout_secs: Some(
                    10,
                ),
            },
        ),
    ],
    check: Theme {
        kind: "theme-openbox",
        name: "Onyx-Citrus",
    },
}

